def parse_hhmm(text: str) -> int:
    """Return the number of minutes in an ``"H:MM"`` duration."""
    try:
        hours, minutes_str = text.split(":")
    except ValueError:
        raise ValueError(f"Entry must be in H:MM format, got: {text}")

    minutes = int(minutes_str)
    if minutes >= 60:
        raise ValueError(f"Minutes must be below 60, got: {minutes}")

    return int(hours) * 60 + minutes
